import * as React from "react";

export interface ShinyNeonBadgeProps
  extends React.HTMLAttributes<HTMLSpanElement> {
  pulse?: boolean;
  children?: React.ReactNode;
}

/**
 * ShinyNeonBadge — pill-style status badge with a soft pulsing dot.
 * Uses primary tokens so it adapts to light and dark themes automatically.
 */
export function ShinyNeonBadge({
  pulse = true,
  className,
  children = "Registry Live",
  ...rest
}: ShinyNeonBadgeProps) {
  return (
    <span
      {...rest}
      className={[
        "inline-flex items-center gap-1.5 px-3 py-1 rounded-full bg-primary/10 border border-primary/20 text-xs font-semibold text-primary",
        className,
      ]
        .filter(Boolean)
        .join(" ")}
    >
      <span
        aria-hidden
        className={[
          "h-1.5 w-1.5 rounded-full bg-primary",
          pulse ? "animate-pulse motion-reduce:animate-none" : "",
        ]
          .filter(Boolean)
          .join(" ")}
      />
      {children}
    </span>
  );
}

export default ShinyNeonBadge;
